-- ============================================================
-- SEED EXT 6: Módulo 17 — Non-Defining Clauses (ex 203-300)
-- Tópicos: relative não-definidoras com vírgulas, apositivas,
-- reduced relatives, participle clauses, estruturas formais avançadas
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'non-defining-clauses';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo non-defining-clauses não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 71: Non-defining relatives com who/which
  (cid,71,203,'gap_fill','The commission, _____ (which) _____ (establish/passive) in _____ (response) to _____ (the) widespread _____ (criticism) of existing oversight arrangements, _____ (present) its findings to _____ (the) parliament last week — _____ (findings) _____ (which), _____ (predictably), _____ (challenge) _____ (several) _____ (of) _____ (the) _____ government''s core assumptions.','which / was established / response / the / criticism / presented / the / findings / which / predictably / challenged / several / of / the / government''s',NULL,'Non-defining RC ''which was established in response'' + ''findings, which...challenged'' — extra info, commas required.','hard'),
  (cid,71,204,'gap_fill','Professor Chen, _____ (who) _____ (serve) as _____ (the) lead investigator on _____ (this) project for _____ (three) _____ (year), _____ (argue) that _____ (the) _____ (result) _____ (call) for _____ (a) fundamental _____ (revision) of _____ (the) prevailing _____ (theoretical) _____ (framework).','who / served / the / this / three / years / argues / the / results / call / a / fundamental / revision / the / prevailing / theoretical / framework',NULL,'''Professor Chen, who served as lead investigator, argues'' — non-defining who-clause adds biographical context.','hard'),
  (cid,71,205,'gap_fill','The _____ (2019) _____ (report), _____ (which) _____ (remain) _____ (the) most _____ (comprehensive) _____ (survey) of _____ (its) _____ (kind) to _____ (have/passive), _____ (identify) _____ (several) _____ (gap) in _____ (the) _____ (current) _____ (regulatory) _____ (architecture) that _____ (persist) _____ (unaddress) to _____ (this) _____ (day).','2019 / report / which / remains / the / most / comprehensive / survey / its / kind / have been published / identified / several / gaps / the / current / regulatory / architecture / persist / unaddressed / this / day',NULL,'''The 2019 report, which remains the most comprehensive survey, identified gaps'' — non-defining clause with superlative.','hard'),
  (cid,71,206,'gap_fill','The _____ (agreement), _____ (which) _____ (negotiate/passive) _____ (over) _____ (several) _____ (year) of _____ (intensive) _____ (diplomacy), _____ (represent) _____ (a) _____ (significant) _____ (step) _____ (forward) — though _____ (its) _____ (critics), _____ (who) _____ (include) _____ (several) _____ (major) _____ (environmental) _____ (organization), _____ (argue) _____ (that) _____ (it) _____ (not/go) _____ (far) _____ (enough).','agreement / which / was negotiated / over / several / years / intensive / diplomacy / represents / a / significant / step / forward / its / critics / who / include / several / major / environmental / organizations / argue / that / it / does not go / far / enough',NULL,'Two non-defining clauses: ''which was negotiated over several years'' + ''who include several major environmental organizations.''','hard'),
  (cid,71,207,'gap_fill','The _____ (Bank''s) _____ (Governor), _____ (who) _____ (announce) _____ (the) _____ (decision) at _____ (a) _____ (press) _____ (conference) _____ (yesterday), _____ (acknowledge) _____ (that) _____ (the) _____ (move) _____ (likely) _____ (to) _____ (increase) _____ (short-term) _____ (borrowing) _____ (cost), _____ (which) _____ (affect) _____ (primarily) those _____ (with) _____ (variable-rate) _____ (mortgage).','Bank''s / Governor / who / announced / the / decision / a / press / conference / yesterday / acknowledged / that / the / move / was likely / to / increase / short-term / borrowing / costs / which / affects / primarily / those / with / variable-rate / mortgages',NULL,'''Governor, who announced... acknowledged'' + ''costs, which affects primarily those with variable-rate mortgages.''','hard'),
  (cid,71,208,'multiple_choice','Which sentence uses a non-defining relative clause MOST correctly?','The new policy, which was drafted after extensive consultation with industry stakeholders, takes effect on the first of January.','["The new policy which was drafted after extensive consultation takes effect on the first of January.","The new policy, which was drafted after extensive consultation with industry stakeholders, takes effect on the first of January.","The new policy, that was drafted after extensive consultation, takes effect on the first of January.","The new policy, which was drafted after extensive consultation, it takes effect on the first of January."]','Non-defining clauses require commas and cannot use ''that.'' Option A omits commas (becomes defining). Option C uses ''that'' (incorrect). Option D has a redundant ''it.''','easy'),
  (cid,71,209,'gap_fill','The _____ (minister), _____ (who) _____ (previously) _____ (serve) _____ (as) _____ (the) _____ (director) _____ (of) _____ (the) _____ (national) _____ (audit) _____ (office), _____ (bring) _____ (a) _____ (rare) _____ (combination) _____ (of) _____ (technical) _____ (expertise) and _____ (political) _____ (experience) to _____ (the) _____ (role) — _____ (a) _____ (combination), _____ (it) _____ (should) _____ (note/passive), _____ (that) _____ (is) _____ (rarely) _____ (find) in _____ (senior) _____ (government) _____ (position).','minister / who / previously / served / as / the / director / of / the / national / audit / office / brings / a / rare / combination / of / technical / expertise / political / experience / the / role / a / combination / it / should / be noted / that / is / rarely / found / senior / government / positions',NULL,'''Minister, who previously served'' + ''a combination, it should be noted, that is rarely found'' — parenthetical observation.','hard'),
  (cid,71,210,'gap_fill','The _____ (program), _____ (which) _____ (originally) _____ (design/passive) _____ (as) _____ (a) _____ (pilot) _____ (initiative), _____ (expand/passive) _____ (nationally) _____ (after) _____ (early) _____ (evaluation) _____ (show) _____ (promising) _____ (result) — _____ (result) _____ (that) _____ (should) _____ (note/passive) _____ (have/passive) _____ (their) _____ (limitation).','program / which / originally / was designed / as / a / pilot / initiative / was expanded / nationally / after / early / evaluations / showed / promising / results / results / that / should / be noted / have / their / limitations',NULL,'''Program, which was originally designed as a pilot, was expanded'' + ''results that should be noted have their limitations.''','hard'),

  -- BLOCK 72: Non-defining clauses com whose e whom
  (cid,72,211,'gap_fill','The _____ (researcher), _____ (whose) _____ (methodology) _____ (has) _____ (come) _____ (under) _____ (increasing) _____ (scrutiny), _____ (defend) _____ (her) _____ (approach) _____ (on) _____ (the) _____ (grounds) _____ (that) _____ (the) _____ (available) _____ (alternative) _____ (produce) _____ (less) _____ (reliable) _____ (estimate).','researcher / whose / methodology / has / come / under / increasing / scrutiny / defends / her / approach / on / the / grounds / that / the / available / alternatives / produce / less / reliable / estimates',NULL,'''Researcher, whose methodology has come under scrutiny, defends'' — non-defining whose-clause.','hard'),
  (cid,72,212,'gap_fill','The _____ (committee), _____ (whose) _____ (recommendation) _____ (carry) _____ (significant) _____ (weight) _____ (with) _____ (the) _____ (minister), _____ (has) _____ (not) _____ (yet) _____ (release/passive) _____ (its) _____ (final) _____ (report), _____ (which) _____ (expect/passive) _____ (to) _____ (address) _____ (several) _____ (controversial) _____ (issue) _____ (that) _____ (have) _____ (divide/passive) _____ (the) _____ (field).','committee / whose / recommendations / carry / significant / weight / with / the / minister / has / not / yet / been released / its / final / report / which / is expected / to / address / several / controversial / issues / that / have / been divided / the / field',NULL,'''Committee, whose recommendations carry weight, has not yet released'' + ''report, which is expected to address issues that have divided the field.''','hard'),
  (cid,72,213,'gap_fill','The _____ (organization''s) _____ (founder), _____ (to) _____ (whom) _____ (much) _____ (of) _____ (its) _____ (current) _____ (success) _____ (attribute/passive), _____ (step) _____ (down) _____ (earlier) _____ (this) _____ (year), _____ (cite) _____ (personal) _____ (reason) — _____ (a) _____ (departure) _____ (which) _____ (surprise) _____ (many) _____ (who) _____ (had) _____ (expect) her _____ (to) _____ (serve) _____ (another) _____ (term).','organization''s / founder / to / whom / much / of / its / current / success / is attributed / stepped / down / earlier / this / year / citing / personal / reasons / a / departure / which / surprised / many / who / had / expected / her / to / serve / another / term',NULL,'''Founder, to whom much success is attributed, stepped down'' + ''a departure, which surprised many who had expected.''','hard'),
  (cid,72,214,'gap_fill','The _____ (delegation), _____ (whose) _____ (composition) _____ (reflect) _____ (the) _____ (full) _____ (diversity) _____ (of) _____ (the) _____ (member) _____ (state), _____ (present) _____ (a) _____ (unified) _____ (position) _____ (despite) _____ (the) _____ (significant) _____ (difference) _____ (that) _____ (exist) _____ (among) _____ (its) _____ (constituent) _____ (part).','delegation / whose / composition / reflects / the / full / diversity / of / the / member / states / presented / a / unified / position / despite / the / significant / differences / that / existed / among / its / constituent / parts',NULL,'''Delegation, whose composition reflects diversity, presented unified position'' — formal diplomatic context.','hard'),
  (cid,72,215,'multiple_choice','Which sentence MOST correctly uses ''whose'' in a non-defining clause?','The policy document, whose conclusions have been widely cited, was produced by a team of independent experts.','["The policy document whose conclusions have been widely cited was produced by a team of independent experts.","The policy document, whose conclusions have been widely cited, was produced by a team of independent experts.","The policy document, which conclusions have been widely cited, was produced by a team of independent experts.","The policy document, whom conclusions have been widely cited, was produced by a team of independent experts."]','Non-defining: commas + ''whose'' (possessive relative). Option A is defining (no commas). Options C/D use incorrect forms.','easy'),
  (cid,72,216,'gap_fill','The _____ (author), _____ (whose) _____ (previous) _____ (work) _____ (has) _____ (been) _____ (influential) _____ (in) _____ (shaping) _____ (the) _____ (field), _____ (adopt) _____ (a) _____ (more) _____ (cautious) _____ (position) _____ (in) _____ (this) _____ (volume), _____ (which) _____ (suggest) _____ (a) _____ (significant) _____ (shift) _____ (in) _____ (her) _____ (thinking).','author / whose / previous / work / has / been / influential / in / shaping / the / field / adopts / a / more / cautious / position / in / this / volume / which / suggests / a / significant / shift / in / her / thinking',NULL,'''Author, whose previous work has been influential, adopts'' + ''position, which suggests a significant shift.''','hard'),
  (cid,72,217,'gap_fill','The _____ (government), _____ (whose) _____ (mandate) _____ (expire) _____ (next) _____ (year), _____ (announce) _____ (a) _____ (series) _____ (of) _____ (reform) _____ (measure), _____ (several) _____ (of) _____ (which) _____ (require) _____ (constitutional) _____ (amendment) — _____ (an) _____ (ambitious) _____ (agenda) _____ (that) _____ (many) _____ (observer) _____ (view) _____ (with) _____ (skepticism).','government / whose / mandate / expires / next / year / announced / a / series / of / reform / measures / several / of / which / require / constitutional / amendments / an / ambitious / agenda / that / many / observers / view / with / skepticism',NULL,'''Government, whose mandate expires, announced measures, several of which require amendments — an agenda that observers view with skepticism.''','hard'),
  (cid,72,218,'gap_fill','The _____ (panel), _____ (to) _____ (whom) _____ (the) _____ (final) _____ (decision) _____ (delegate/passive), _____ (include) _____ (three) _____ (independent) _____ (expert), _____ (none) _____ (of) _____ (whom) _____ (has) _____ (any) _____ (financial) _____ (interest) _____ (in) _____ (the) _____ (outcome).','panel / to / whom / the / final / decision / was delegated / includes / three / independent / experts / none / of / whom / has / any / financial / interest / in / the / outcome',NULL,'''Panel, to whom the final decision was delegated, includes experts, none of whom has any financial interest.''','hard'),

  -- BLOCK 73: Participle clauses como equivalentes de non-defining
  (cid,73,219,'gap_fill','The _____ (report), _____ (publish) _____ (in) _____ (2023) _____ (after) _____ (five) _____ (year) _____ (of) _____ (research), _____ (draw) _____ (on) _____ (data) _____ (collect) _____ (from) _____ (over) _____ (forty) _____ (country) _____ (across) _____ (three) _____ (continent), _____ (provide) _____ (what) _____ (its) _____ (author) _____ (describe) _____ (as) _____ (the) _____ (most) _____ (comprehensive) _____ (analysis) _____ (yet) _____ (undertake).','report / published / in / 2023 / after / five / years / of / research / drawing / on / data / collected / from / over / forty / countries / across / three / continents / provides / what / its / authors / describe / as / the / most / comprehensive / analysis / yet / undertaken',NULL,'Participle phrase ''published in 2023 after five years'' + ''drawing on data collected'' = non-defining reduced relatives.','hard'),
  (cid,73,220,'gap_fill','The _____ (minister), _____ (speak) _____ (at) _____ (a) _____ (conference) _____ (in) _____ (Geneva), _____ (outline) _____ (the) _____ (government''s) _____ (new) _____ (approach) _____ (to) _____ (the) _____ (issue), _____ (acknowledge) _____ (that) _____ (the) _____ (previous) _____ (policy) _____ (had) _____ (fall) _____ (short) _____ (of) _____ (its) _____ (stated) _____ (objective).','minister / speaking / at / a / conference / in / Geneva / outlined / the / government''s / new / approach / to / the / issue / acknowledging / that / the / previous / policy / had / fallen / short / of / its / stated / objectives',NULL,'''Minister, speaking at a conference in Geneva, outlined'' + ''acknowledging that'' — participle clauses as non-defining equivalents.','hard'),
  (cid,73,221,'gap_fill','The _____ (institution), _____ (found/passive) _____ (over) _____ (a) _____ (century) _____ (ago), _____ (continue) _____ (to) _____ (adapt) _____ (to) _____ (a) _____ (changing) _____ (environment), _____ (demonstrate) _____ (the) _____ (kind) _____ (of) _____ (organizational) _____ (resilience) _____ (that) _____ (distinguish) _____ (durable) _____ (institution) _____ (from) _____ (those) _____ (that) _____ (collapse) _____ (under) _____ (pressure).','institution / founded / over / a / century / ago / continues / to / adapt / to / a / changing / environment / demonstrating / the / kind / of / organizational / resilience / that / distinguishes / durable / institutions / those / that / collapse / under / pressure',NULL,'''Founded over a century ago'' + ''demonstrating the kind of resilience'' — past and present participle non-defining clauses.','hard'),
  (cid,73,222,'gap_fill','The _____ (proposal), _____ (initially) _____ (oppose/passive) _____ (by) _____ (several) _____ (key) _____ (stakeholder), _____ (eventually) _____ (gain) _____ (broad) _____ (support) _____ (after) _____ (its) _____ (author) _____ (agree) _____ (to) _____ (incorporate) _____ (a) _____ (number) _____ (of) _____ (amendment), _____ (thereby) _____ (address) _____ (the) _____ (concern) _____ (raise/passive) _____ (during) _____ (consultation).','proposal / initially / opposed / by / several / key / stakeholders / eventually / gained / broad / support / after / its / authors / agreed / to / incorporate / a / number / of / amendments / thereby / addressing / the / concerns / raised / during / consultation',NULL,'''Initially opposed by stakeholders'' + ''thereby addressing the concerns raised during consultation.''','hard'),
  (cid,73,223,'gap_fill','The _____ (committee''s) _____ (report), _____ (run) _____ (to) _____ (several) _____ (hundred) _____ (page) _____ (and) _____ (cover) _____ (every) _____ (aspect) _____ (of) _____ (the) _____ (issue), _____ (struggle) _____ (to) _____ (gain) _____ (traction) _____ (with) _____ (a) _____ (government) _____ (look) _____ (for) _____ (simpler) _____ (solution).','committee''s / report / running / to / several / hundred / pages / and / covering / every / aspect / of / the / issue / struggled / to / gain / traction / with / a / government / looking / for / simpler / solutions',NULL,'''Running to several hundred pages and covering every aspect'' + ''a government looking for simpler solutions.''','hard'),
  (cid,73,224,'multiple_choice','Which participle clause functions MOST effectively as a non-defining modifier in formal writing?','The proposal, having been revised three times in response to stakeholder feedback, was finally approved by the board.','["The proposal, been revised three times in response to stakeholder feedback, was finally approved by the board.","The proposal, revised three times in response to stakeholder feedback, was finally approved by the board.","The proposal, having been revised three times in response to stakeholder feedback, was finally approved by the board.","The proposal, that was revised three times in response to stakeholder feedback, was finally approved by the board."]','''Having been revised'' = perfect passive participle, most precise for completed prior action. Option B is also correct but less precise about timing. Option D uses ''that'' (defining, not non-defining).','medium'),
  (cid,73,225,'gap_fill','The _____ (analysis), _____ (base) _____ (on) _____ (data) _____ (collect) _____ (across) _____ (fifteen) _____ (year), _____ (reveal) _____ (pattern) _____ (not) _____ (previously) _____ (identify) _____ (in) _____ (the) _____ (literature) — _____ (finding) _____ (that) _____ (challenge) _____ (several) _____ (assumption) _____ (long) _____ (hold) _____ (in) _____ (the) _____ (field).','analysis / based / on / data / collected / across / fifteen / years / revealed / patterns / not / previously / identified / in / the / literature / findings / that / challenged / several / assumptions / long / held / in / the / field',NULL,'''Analysis, based on data collected'' + ''findings that challenged assumptions long held in the field.''','hard'),
  (cid,73,226,'gap_fill','The _____ (agency), _____ (create/passive) _____ (specifically) _____ (to) _____ (oversee) _____ (the) _____ (implementation) _____ (of) _____ (the) _____ (reform), _____ (find) _____ (itself) _____ (undermining) _____ (by) _____ (a) _____ (lack) _____ (of) _____ (resource) _____ (and) _____ (authority), _____ (a) _____ (problem) _____ (that) _____ (reflect) _____ (the) _____ (broader) _____ (failure) _____ (to) _____ (align) _____ (means) _____ (with) _____ (end).','agency / created / specifically / to / oversee / the / implementation / of / the / reform / found / itself / undermined / by / a / lack / of / resources / and / authority / a / problem / that / reflects / the / broader / failure / to / align / means / with / ends',NULL,'''Created specifically to oversee the implementation'' (participle) + ''a problem that reflects the broader failure.''','hard'),

  -- BLOCK 74: Apositivas — noun phrases como não-definidoras
  (cid,74,227,'gap_fill','The _____ (Bretton) _____ (Woods) _____ (institutions), _____ (the) _____ (International) _____ (Monetary) _____ (Fund) _____ (and) _____ (the) _____ (World) _____ (Bank), _____ (face) _____ (growing) _____ (pressure) _____ (to) _____ (reform) _____ (their) _____ (governance) _____ (structure) _____ (to) _____ (reflect) _____ (the) _____ (shift) _____ (in) _____ (the) _____ (global) _____ (economic) _____ (landscape).','Bretton / Woods / institutions / the / International / Monetary / Fund / and / the / World / Bank / face / growing / pressure / to / reform / their / governance / structures / to / reflect / the / shifts / in / the / global / economic / landscape',NULL,'Appositive non-defining: ''the Bretton Woods institutions, the International Monetary Fund and the World Bank, face'' — appositive renaming.','medium'),
  (cid,74,228,'gap_fill','The _____ (principle) _____ (of) _____ (subsidiarity), _____ (the) _____ (idea) _____ (that) _____ (decision) _____ (should) _____ (be) _____ (make/passive) _____ (at) _____ (the) _____ (lowest) _____ (feasible) _____ (level) _____ (of) _____ (governance), _____ (occupy) _____ (a) _____ (central) _____ (place) _____ (in) _____ (the) _____ (architecture) _____ (of) _____ (the) _____ (European) _____ (Union).','principle / of / subsidiarity / the / idea / that / decisions / should / be / made / at / the / lowest / feasible / level / of / governance / occupies / a / central / place / in / the / architecture / of / the / European / Union',NULL,'''Subsidiarity, the idea that decisions should be made at the lowest feasible level'' — appositive defining the concept.','medium'),
  (cid,74,229,'gap_fill','The _____ (concept) _____ (of) _____ (path) _____ (dependency), _____ (the) _____ (observation) _____ (that) _____ (historical) _____ (choice) _____ (constrain) _____ (future) _____ (option), _____ (offer) _____ (a) _____ (powerful) _____ (lens) _____ (through) _____ (which) _____ (to) _____ (understand) _____ (why) _____ (institutional) _____ (reform) _____ (is) _____ (often) _____ (so) _____ (difficult) _____ (even) _____ (when) _____ (the) _____ (case) _____ (for) _____ (change) _____ (is) _____ (clear).','concept / of / path / dependency / the / observation / that / historical / choices / constrain / future / options / offers / a / powerful / lens / through / which / to / understand / why / institutional / reform / is / often / so / difficult / even / when / the / case / for / change / is / clear',NULL,'''Path dependency, the observation that historical choices constrain future options, offers'' — appositive non-defining.','hard'),
  (cid,74,230,'gap_fill','The _____ (government''s) _____ (flagship) _____ (policy), _____ (a) _____ (program) _____ (design/passive) _____ (to) _____ (provide) _____ (universal) _____ (access) _____ (to) _____ (primary) _____ (health) _____ (care), _____ (have) _____ (meet/passive) _____ (with) _____ (mix) _____ (result) _____ (in) _____ (its) _____ (first) _____ (year) _____ (of) _____ (operation).','government''s / flagship / policy / a / program / designed / to / provide / universal / access / to / primary / health / care / has / been met / with / mixed / results / in / its / first / year / of / operation',NULL,'''Flagship policy, a program designed to provide universal access, has been met with mixed results.''','hard'),
  (cid,74,231,'gap_fill','The _____ (phenomenon) _____ (of) _____ (regulatory) _____ (capture), _____ (a) _____ (process) _____ (by) _____ (which) _____ (regulators) _____ (come) _____ (to) _____ (advance) _____ (the) _____ (interest) _____ (of) _____ (those) _____ (they) _____ (are) _____ (intend/passive) _____ (to) _____ (regulate), _____ (represent) _____ (one) _____ (of) _____ (the) _____ (most) _____ (persistent) _____ (challenge) _____ (in) _____ (the) _____ (design) _____ (of) _____ (effective) _____ (oversight) _____ (system).','phenomenon / of / regulatory / capture / a / process / by / which / regulators / come / to / advance / the / interests / of / those / they / are / intended / to / regulate / represents / one / of / the / most / persistent / challenges / in / the / design / of / effective / oversight / systems',NULL,'''Regulatory capture, a process by which regulators come to advance interests'' — appositive defining process.','hard'),
  (cid,74,232,'multiple_choice','Which appositive non-defining construction is MOST formally correct?','The concept of democratic backsliding, a term used to describe the gradual erosion of democratic norms and institutions, has attracted increasing scholarly attention.','["The concept of democratic backsliding — a term used to describe the gradual erosion of democratic norms — has attracted attention.","The concept of democratic backsliding, a term used to describe the gradual erosion of democratic norms and institutions, has attracted increasing scholarly attention.","The concept of democratic backsliding, which is a term used to describe the gradual erosion of democratic norms and institutions, has attracted increasing scholarly attention.","The concept of democratic backsliding that describes the gradual erosion of democratic norms has attracted increasing scholarly attention."]','Both A and B are correct; B is more complete. Option C adds ''which is'' (wordy but acceptable). Option D is defining (no commas, ''that'').','medium'),
  (cid,74,233,'gap_fill','The _____ (commission''s) _____ (core) _____ (recommendation), _____ (a) _____ (proposal) _____ (to) _____ (establish) _____ (an) _____ (independent) _____ (body) _____ (with) _____ (the) _____ (authority) _____ (to) _____ (investigate) _____ (allegation) _____ (of) _____ (misconduct), _____ (face) _____ (strong) _____ (opposition) _____ (from) _____ (those) _____ (whose) _____ (behavior) _____ (it) _____ (is) _____ (design/passive) _____ (to) _____ (scrutinize).','commission''s / core / recommendation / a / proposal / to / establish / an / independent / body / with / the / authority / to / investigate / allegations / of / misconduct / faces / strong / opposition / from / those / whose / behavior / it / is / designed / to / scrutinize',NULL,'''Core recommendation, a proposal to establish an independent body, faces opposition from those whose behavior it is designed to scrutinize.''','hard'),
  (cid,74,234,'gap_fill','The _____ (2015) _____ (Paris) _____ (Agreement), _____ (the) _____ (most) _____ (ambitious) _____ (multilateral) _____ (accord) _____ (ever) _____ (reach/passive) _____ (on) _____ (climate) _____ (change), _____ (set) _____ (target) _____ (that) _____ (require) _____ (fundamental) _____ (transformation) _____ (of) _____ (energy) _____ (system) _____ (across) _____ (the) _____ (world).','2015 / Paris / Agreement / the / most / ambitious / multilateral / accord / ever / reached / on / climate / change / set / targets / that / require / fundamental / transformation / of / energy / systems / across / the / world',NULL,'''Paris Agreement, the most ambitious multilateral accord ever reached on climate change, set targets that require transformation.''','hard'),

  -- BLOCK 75: TOEFL Reading — Non-defining clauses
  (cid,75,235,'multiple_choice','[TOEFL Reading] ''The policy, which has been in effect for three years, has produced mixed results.'' What does the non-defining clause add?','Additional information about how long the policy has been in effect.','["It identifies which policy is being discussed","Additional information about how long the policy has been in effect.","It explains why the results are mixed","It introduces a contrast with another policy"]','Non-defining RC between commas = extra, non-essential information about an already-identified noun.','easy'),
  (cid,75,236,'gap_fill','[TOEFL Reading] ''The committee, _____ (whose) _____ recommendations _____ (carry) significant weight, _____ (has/yet/release/not/passive) its final report.'' The correct forms are:','whose / carry / has not yet been released',NULL,'''Whose'' = possessive relative; ''carry'' (present plural); ''has not yet been released'' (passive present perfect).','medium'),
  (cid,75,237,'gap_fill','[TOEFL Reading] ''The institution, _____ (establish/passive) in _____ the aftermath of _____ the conflict, _____ (mandate/passive) _____ to address _____ the legacy _____ of _____ human rights violations.'' Best forms?','established / the aftermath / the conflict / was mandated / to address / the legacy / of / human rights violations',NULL,'''Established in the aftermath'' (past participle non-defining) + ''was mandated to address.''','medium'),
  (cid,75,238,'multiple_choice','[TOEFL Reading] ''The researchers, none of whom had prior experience in the region, conducted a six-month field study.'' The phrase ''none of whom'' is:','A quantified non-defining relative referring to ''the researchers.''','[''A defining relative clause'',''A quantified non-defining relative referring to '''the researchers.''''',''A result clause'',''An appositive noun phrase"]','''None of whom'' = quantified partitive non-defining relative. Commas confirm non-defining function.','easy'),
  (cid,75,239,'gap_fill','[TOEFL Reading] ''The evidence, _____ (accumulate/passive) over several decades, _____ (point) to _____ a systematic pattern _____ (that) _____ (not/explain/can/passive) by _____ chance alone.'' Best forms?','accumulated / points / a / systematic / pattern / that / cannot be explained / chance',NULL,'''Evidence, accumulated over several decades, points'' (past participle non-defining) + ''pattern that cannot be explained by chance.''','medium'),
  (cid,75,240,'gap_fill','[TOEFL Reading] ''The director, _____ (who) _____ (previously/serve) as a senior adviser to the government, _____ (bring) _____ a unique perspective to _____ the role.'' Best forms?','who / had previously served / brings / a',NULL,'''Director, who had previously served, brings a unique perspective'' — non-defining who-clause.','easy'),
  (cid,75,241,'multiple_choice','[TOEFL Reading] ''The proposal, originally designed as a short-term measure, has become a permanent feature of the regulatory framework.'' What does ''originally designed as a short-term measure'' tell us?','Additional background about the proposal''s original intent.','["It tells us which proposal is being discussed","Additional background about the proposal''s original intent.","It explains why the proposal became permanent","It identifies who designed the proposal"]','Participial non-defining phrase between commas = background information, not identification.','easy'),
  (cid,75,242,'gap_fill','[TOEFL Reading] ''The report, _____ (run) _____ to three hundred pages and _____ (cover) every aspect of the crisis, _____ (release/passive) _____ to widespread public attention.'' Best forms?','running / to three hundred pages / covering / was released',NULL,'''Running to pages and covering every aspect'' = present participle non-defining phrase; ''was released'' = passive main verb.','medium'),

  -- BLOCK 76: TOEFL Speaking — Non-defining clauses
  (cid,76,243,'production','[TOEFL Speaking — 45s] Summarize what the reading says about a new institutional initiative, using non-defining clauses throughout.','',NULL,'The reading describes a new institutional initiative, which was launched in response to widespread criticism of existing oversight arrangements, and evaluates its prospects for success. The initiative, which represents the most ambitious reform attempted in the sector in over a decade, establishes an independent review body with the authority to investigate allegations of misconduct and to make binding recommendations. The board members, who were selected through an open competitive process, are required to have no prior affiliation with the regulated industry — a safeguard, it should be noted, that was absent from the previous oversight structure. The reading concludes that the reform, whose design incorporates lessons from comparable initiatives in other jurisdictions, has the potential to significantly improve the quality of oversight, provided that it receives the political support and resources that effective implementation requires.','hard'),
  (cid,76,244,'production','[TOEFL Speaking — 45s] The professor critiques an institutional reform. Use non-defining clauses throughout.','',NULL,'The professor critiques a recent institutional reform, whose designers, she argues, have underestimated the political economy of implementation. The reform, which was approved after two years of consultation, establishes a new oversight body with significant formal authority. However, the professor notes that the body, whose budget depends on the annual appropriations process, is vulnerable to the very political pressures it is supposed to be insulated from. She also observes that the reform''s success depends on the cooperation of the agencies it is meant to oversee — agencies, none of which had any formal input into the design of the oversight framework, and many of which view the new body with suspicion. The professor concludes that the reform, however well-designed in principle, faces implementation challenges that its architects have not adequately addressed.','hard'),
  (cid,76,245,'production','[TOEFL Speaking — 60s] Compare what the reading and professor say about the effectiveness of regulatory oversight, using non-defining clauses throughout.','',NULL,'The reading and the professor both examine the conditions under which regulatory oversight is effective, but they reach different conclusions. The reading, which draws on a comprehensive comparative analysis of oversight systems across twenty-three countries, argues that the formal design of the oversight structure — its independence, its mandate, and the powers available to it — is the primary determinant of effectiveness. It cites the cases of several regulatory agencies, none of which had formal independence but all of which nonetheless achieved significant enforcement outcomes, as evidence that strong formal design is a reliable predictor of performance. The professor, whose own research focuses on the informal dimensions of regulatory behavior, challenges this conclusion. She argues that the agencies the reading cites as evidence of design-driven effectiveness — several of which she has studied in depth — achieved their results despite their formal design rather than because of it, through the exercise of informal leadership and the cultivation of relationships with the regulated industries that allowed them to secure voluntary compliance. Her conclusion, which challenges a central assumption of the regulatory design literature, is that the quality of the people leading the regulatory body matters at least as much as the formal structure within which they operate — a conclusion with significant implications for how we think about regulatory reform.','hard'),
  (cid,76,246,'gap_fill','[TOEFL Speaking] The professor, _____ (whose) _____ research _____ (focus) on informal governance, _____ (argue) that the formal rules, _____ (which) _____ (design/passive) without attention to _____ the cultural context, _____ (fail) _____ to achieve _____ their intended effect.','whose / focuses / argues / which / were designed / the / failed',NULL,'''Professor, whose research focuses, argues'' + ''formal rules, which were designed without attention to cultural context, failed.''','hard'),

  -- BLOCK 77: TOEFL Writing — Non-defining clauses
  (cid,77,247,'production','[TOEFL Writing — 200 words] Write a paragraph on the role of independent oversight bodies, using non-defining clauses throughout.','',NULL,'Independent oversight bodies, which have become an increasingly standard feature of governance architecture across democratic systems, perform functions that are essential to the maintenance of accountability and public trust. The most effective of these bodies, whose independence is protected by law and whose budgets are not subject to the discretion of those they oversee, combine formal authority with operational autonomy in ways that allow them to pursue allegations of misconduct without political interference. The ombudsman systems of Scandinavian countries, which are among the oldest examples of independent oversight in the modern sense, have demonstrated that bodies of this kind can develop institutional cultures, sustained over generations, that remain genuinely committed to their mandate even when powerful interests would prefer a less rigorous approach. The challenge, which has become increasingly apparent as oversight bodies have proliferated, is ensuring that independence does not become isolation — that bodies which are insulated from political pressure are not also insulated from the practical feedback that would allow them to improve their performance. The most sophisticated oversight systems are those that have found a way to combine formal independence with informal accountability to the communities they serve — a balance, it should be acknowledged, that is easier to describe than to achieve.','hard'),
  (cid,77,248,'production','[TOEFL Writing — 200 words] Write a body paragraph on what determines institutional resilience, using non-defining clauses throughout.','',NULL,'Institutional resilience, a concept that has attracted considerable scholarly attention in recent years, refers to the capacity of an institution to maintain its core functions and values in the face of environmental pressures that would otherwise destabilize it. The institutions that have demonstrated the greatest resilience, several of which have survived for centuries across dramatically changing political and economic environments, share a set of characteristics that can be identified with some consistency. They possess clear and widely understood mandates, which are reinforced by organizational cultures that take those mandates seriously at every level. They have leadership structures, designed to limit the capacity of any single individual to compromise the institution''s integrity, that distribute authority sufficiently to prevent capture. And they have developed adaptive mechanisms — review processes, feedback loops, and deliberate learning systems — that allow them to modify their practices in response to what they discover about what is working and what is not. The institutions that have proved least resilient, by contrast, tend to be those whose mandates are vague, whose governance is concentrated in the hands of individuals whose personal interests may diverge from the institutional mission, and whose cultures tolerate the erosion of standards that began with small compromises and gradually extended to more significant ones.','hard'),
  (cid,77,249,'gap_fill','[TOEFL Writing] The _____ (framework), _____ (which) _____ (develop/passive) _____ (over) _____ (several) _____ (year) _____ (of) _____ (intensive) _____ (deliberation), _____ (represent) _____ (the) _____ (most) _____ (comprehensive) _____ (attempt) _____ (to) _____ (date) _____ (to) _____ (address) _____ (the) _____ (governance) _____ (challenge) _____ (pose/passive) _____ (by) _____ (the) _____ (emergence) _____ (of) _____ (digital) _____ (platform).','framework / which / was developed / over / several / years / intensive / deliberation / represents / the / most / comprehensive / attempt / to / date / to / address / the / governance / challenges / posed / by / the / emergence / of / digital / platforms',NULL,'''Framework, which was developed over several years, represents the most comprehensive attempt to address challenges posed by.''','hard'),
  (cid,77,250,'gap_fill','[TOEFL Writing] The _____ (analysis), _____ (which) _____ (draw) _____ (on) _____ (both) _____ (quantitative) _____ (and) _____ (qualitative) _____ (source), _____ (reach) _____ (a) _____ (conclusion) _____ (that) _____ (challenge) _____ (several) _____ (assumption) _____ (long) _____ (take/passive) _____ (for) _____ (granted) _____ (in) _____ (the) _____ (literature).','analysis / which / draws / on / both / quantitative / and / qualitative / sources / reaches / a / conclusion / that / challenges / several / assumptions / long / taken / for / granted / in / the / literature',NULL,'''Analysis, which draws on both sources, reaches a conclusion that challenges assumptions long taken for granted.''','hard'),
  (cid,77,251,'gap_fill','[TOEFL Writing] The _____ (evidence), _____ (accumulate/passive) _____ (over) _____ (three) _____ (decade) _____ (of) _____ (research), _____ (support) _____ (the) _____ (conclusion) _____ (that) _____ (institutional) _____ (quality) _____ (matter) _____ (more) _____ (than) _____ (any) _____ (other) _____ (single) _____ (factor) _____ (in) _____ (determining) _____ (long-term) _____ (development) _____ (outcome).','evidence / accumulated / over / three / decades / of / research / supports / the / conclusion / that / institutional / quality / matters / more / than / any / other / single / factor / in / determining / long-term / development / outcomes',NULL,'''Evidence, accumulated over three decades, supports the conclusion that institutional quality matters more than any other single factor.''','hard'),
  (cid,77,252,'gap_fill','[TOEFL Writing] The _____ (author''s) _____ (central) _____ (argument), _____ (which) _____ (have) _____ (significant) _____ (implication) _____ (for) _____ (how) _____ (we) _____ (think) _____ (about) _____ (reform), _____ (challenge) _____ (the) _____ (prevailing) _____ (assumption) _____ (that) _____ (formal) _____ (design) _____ (is) _____ (sufficient) _____ (to) _____ (ensure) _____ (effective) _____ (governance).','author''s / central / argument / which / has / significant / implications / for / how / we / think / about / reform / challenges / the / prevailing / assumption / that / formal / design / is / sufficient / to / ensure / effective / governance',NULL,'''Author''s central argument, which has significant implications, challenges the prevailing assumption.''','hard'),

  -- BLOCK 78: Gap fills avançados
  (cid,78,253,'gap_fill','The _____ (institution''s) _____ (founding) _____ (charter), _____ (which) _____ (draft/passive) _____ (in) _____ (haste) _____ (under) _____ (conditions) _____ (of) _____ (political) _____ (pressure), _____ (contain) _____ (several) _____ (ambiguity) _____ (that) _____ (have) _____ (prove) _____ (costly) _____ (in) _____ (subsequent) _____ (dispute) _____ (over) _____ (jurisdiction) _____ (and) _____ (mandate).','institution''s / founding / charter / which / was drafted / in / haste / under / conditions / of / political / pressure / contains / several / ambiguities / that / have / proved / costly / in / subsequent / disputes / over / jurisdiction / mandate',NULL,'''Founding charter, which was drafted in haste under conditions of political pressure, contains ambiguities that have proved costly.''','hard'),
  (cid,78,254,'gap_fill','The _____ (reform) _____ (package), _____ (negotiate/passive) _____ (over) _____ (eighteen) _____ (month) _____ (of) _____ (intensive) _____ (diplomacy), _____ (represent) _____ (a) _____ (carefully) _____ (balance) _____ (compromise) _____ (between) _____ (competing) _____ (interest) — _____ (a) _____ (compromise) _____ (that), _____ (predictably), _____ (satisfy) _____ (no) _____ (party) _____ (entirely).','reform / package / negotiated / over / eighteen / months / of / intensive / diplomacy / represents / a / carefully / balanced / compromise / between / competing / interests / a / compromise / that / predictably / satisfies / no / party / entirely',NULL,'''Reform package, negotiated over eighteen months, represents a carefully balanced compromise — a compromise that satisfies no party entirely.''','hard'),
  (cid,78,255,'gap_fill','The _____ (study), _____ (which) _____ (follow) _____ (a) _____ (cohort) _____ (of) _____ (two) _____ (thousand) _____ (individual) _____ (over) _____ (a) _____ (period) _____ (of) _____ (fifteen) _____ (year), _____ (find) _____ (that) _____ (exposure) _____ (to) _____ (early) _____ (childhood) _____ (program) _____ (have) _____ (lasting) _____ (effect) _____ (on) _____ (educational) _____ (attainment) _____ (and) _____ (labor) _____ (market) _____ (outcome).','study / which / followed / a / cohort / of / two / thousand / individuals / over / a / period / of / fifteen / years / found / that / exposure / to / early / childhood / programs / had / lasting / effects / on / educational / attainment / labor / market / outcomes',NULL,'''Study, which followed a cohort over fifteen years, found that exposure had lasting effects.''','hard'),
  (cid,78,256,'gap_fill','The _____ (minister''s) _____ (announcement), _____ (which) _____ (come) _____ (as) _____ (a) _____ (surprise) _____ (to) _____ (many) _____ (in) _____ (the) _____ (policy) _____ (community), _____ (signal) _____ (a) _____ (significant) _____ (shift) _____ (in) _____ (the) _____ (government''s) _____ (position) _____ (on) _____ (an) _____ (issue) _____ (that) _____ (has) _____ (been) _____ (central) _____ (to) _____ (its) _____ (political) _____ (identity).','minister''s / announcement / which / came / as / a / surprise / to / many / in / the / policy / community / signalled / a / significant / shift / in / the / government''s / position / on / an / issue / that / has / been / central / to / its / political / identity',NULL,'''Minister''s announcement, which came as a surprise, signalled a shift on an issue that has been central to its identity.''','hard'),
  (cid,78,257,'gap_fill','The _____ (document), _____ (prepare/passive) _____ (by) _____ (a) _____ (team) _____ (of) _____ (independent) _____ (expert) _____ (and) _____ (publish/passive) _____ (without) _____ (government) _____ (approval), _____ (paint) _____ (a) _____ (stark) _____ (picture) _____ (of) _____ (the) _____ (gap) _____ (between) _____ (official) _____ (claim) _____ (and) _____ (on-the-ground) _____ (reality).','document / prepared / by / a / team / of / independent / experts / and / published / without / government / approval / paints / a / stark / picture / of / the / gap / between / official / claims / on-the-ground / reality',NULL,'''Document, prepared by a team of experts and published without government approval, paints a stark picture.''','hard'),
  (cid,78,258,'multiple_choice','Which sentence MOST effectively combines two non-defining clauses in formal academic writing?','The policy, which was introduced in 2018 following a decade of advocacy, has achieved several of its stated objectives, though its critics, who include some of the policy''s original architects, argue that its implementation has fallen short.','["The policy, introduced in 2018 following advocacy, achieving several objectives, its critics, including original architects, arguing implementation has fallen short.","The policy was introduced in 2018 following advocacy and has achieved several objectives while critics argue implementation has fallen short.","The policy, which was introduced in 2018 following a decade of advocacy, has achieved several of its stated objectives, though its critics, who include some of the policy''s original architects, argue that its implementation has fallen short.","The policy which was introduced in 2018 following advocacy has achieved objectives although critics who include original architects argue that implementation has fallen short."]','Correct: two non-defining clauses, both with commas; main clause structure preserved; ''though'' for contrast.','medium'),
  (cid,78,259,'gap_fill','The _____ (panel), _____ (establish/passive) _____ (to) _____ (investigate) _____ (the) _____ (allegations), _____ (include) _____ (five) _____ (member), _____ (none) _____ (of) _____ (whom) _____ (have) _____ (any) _____ (prior) _____ (involvement) _____ (in) _____ (the) _____ (matter) _____ (under) _____ (investigation) — _____ (a) _____ (condition) _____ (of) _____ (membership) _____ (that) _____ (ensure) _____ (the) _____ (independence) _____ (of) _____ (the) _____ (process).','panel / established / to / investigate / the / allegations / includes / five / members / none / of / whom / has / any / prior / involvement / in / the / matter / under / investigation / a / condition / of / membership / that / ensures / the / independence / of / the / process',NULL,'''Panel, established to investigate, includes members, none of whom has prior involvement — a condition that ensures independence.''','hard'),
  (cid,78,260,'gap_fill','The _____ (legislation), _____ (pass/passive) _____ (with) _____ (a) _____ (bipartisan) _____ (majority), _____ (represent) _____ (a) _____ (significant) _____ (departure) _____ (from) _____ (the) _____ (confrontational) _____ (approach) _____ (that) _____ (has) _____ (characterize) _____ (the) _____ (legislature) _____ (for) _____ (most) _____ (of) _____ (the) _____ (past) _____ (decade).','legislation / passed / with / a / bipartisan / majority / represents / a / significant / departure / from / the / confrontational / approach / that / has / characterized / the / legislature / for / most / of / the / past / decade',NULL,'''Legislation, passed with a bipartisan majority, represents a departure from the approach that has characterized the legislature.''','hard'),

  -- BLOCK 79: Produção avançada
  (cid,79,261,'production','[TOEFL Writing — 200 words] Write a paragraph on the challenges of international governance, using non-defining clauses throughout.','',NULL,'International governance, which has expanded dramatically in scope and complexity since the end of the Second World War, confronts a fundamental tension between the demands of global coordination and the realities of national sovereignty. The institutions created to manage this tension — the United Nations and its specialized agencies, the World Trade Organization, the International Monetary Fund, and a host of other bodies — operate under mandates that their member states, none of which is willing to cede the authority needed to make global governance genuinely effective, have deliberately kept limited. The result is a governance architecture that is better at producing agreements than at ensuring their implementation — a pattern that reflects not a failure of institutional design but the underlying political reality that states prioritize national autonomy over global effectiveness whenever the two conflict. The most effective international institutions, whose success is frequently cited but rarely fully explained, have managed to navigate this tension by focusing on areas where the interests of member states are strongly aligned, building technical credibility that creates reputational costs for non-compliance, and cultivating relationships with domestic constituencies in member states whose political support makes non-compliance politically costly for national governments. These strategies, which require patience and skill to execute, are difficult to replicate at scale but represent the most plausible pathway to more effective international governance.','hard'),
  (cid,79,262,'production','[TOEFL Writing — 200 words] Write a body paragraph on research methodology, using non-defining clauses throughout.','',NULL,'The methodology used in this study, which was developed in response to the limitations identified in previous approaches to the same research question, combines several techniques in ways that address the most significant sources of bias and error. The primary data source, a longitudinal survey conducted over twelve years, provides the kind of temporal depth that cross-sectional designs, however carefully executed, cannot offer. The sample, which was constructed to be representative of the target population across the dimensions most relevant to the research questions, includes over three thousand participants, none of whom were aware of the specific hypotheses being tested at the time of their participation — a feature that reduces the risk of demand effects distorting the findings. The analytical approach, which draws on recent advances in causal inference methodology, allows the study to make stronger claims about the direction of effects than the correlational designs that have dominated previous work in this area. The key limitation, which is acknowledged explicitly rather than minimized, is that the study was conducted in a single national context, whose specific institutional and cultural characteristics may limit the generalizability of the findings to other settings. Future research, which would ideally be conducted in partnership with teams in other national contexts, could address this limitation through systematic replication.','hard'),
  (cid,79,263,'gap_fill','[TOEFL Writing] The _____ (institution), _____ (which) _____ (find) _____ (itself) _____ (at) _____ (a) _____ (critical) _____ (juncture), _____ (must) _____ (choose) _____ (between) _____ (two) _____ (path), _____ (neither) _____ (of) _____ (which) _____ (offer) _____ (a) _____ (guarantee) _____ (of) _____ (success) _____ (but) _____ (both) _____ (of) _____ (which) _____ (represent) _____ (a) _____ (more) _____ (viable) _____ (option) _____ (than) _____ (continuing) _____ (on) _____ (its) _____ (current) _____ (trajectory).','institution / which / finds / itself / at / a / critical / juncture / must / choose / between / two / paths / neither / of / which / offers / a / guarantee / of / success / both / of / which / represent / a / more / viable / option / than / continuing / on / its / current / trajectory',NULL,'''Institution, which finds itself at a critical juncture, must choose between paths, neither of which offers guarantee, both of which represent.''','hard'),
  (cid,79,264,'gap_fill','[TOEFL Writing] The _____ (argument), _____ (which) _____ (rest) _____ (on) _____ (a) _____ (substantial) _____ (body) _____ (of) _____ (evidence), _____ (has) _____ (not) _____ (persuade) _____ (all) _____ (of) _____ (its) _____ (intended) _____ (audience) — _____ (a) _____ (fact) _____ (that) _____ (reflect) _____ (less) _____ (on) _____ (the) _____ (quality) _____ (of) _____ (the) _____ (argument) _____ (than) _____ (on) _____ (the) _____ (prior) _____ (commitment) _____ (of) _____ (those) _____ (it) _____ (has) _____ (fail) _____ (to) _____ (convince).','argument / which / rests / on / a / substantial / body / of / evidence / has / not / persuaded / all / of / its / intended / audience / a / fact / that / reflects / less / on / the / quality / of / the / argument / than / on / the / prior / commitments / of / those / it / has / failed / to / convince',NULL,'''Argument, which rests on substantial evidence, has not persuaded all — a fact that reflects less on quality than on prior commitments.''','hard'),

  -- BLOCK 80: Exercícios finais
  (cid,80,265,'gap_fill','[TOEFL Writing] The _____ (study), _____ (which) _____ (be) _____ (the) _____ (most) _____ (extensive) _____ (of) _____ (its) _____ (kind) _____ (yet) _____ (undertake/passive), _____ (reach) _____ (conclusion) _____ (that) _____ (have) _____ (significant) _____ (implication) _____ (for) _____ (both) _____ (theory) _____ (and) _____ (practice).','study / which / is / the / most / extensive / of / its / kind / yet / undertaken / reaches / conclusions / that / have / significant / implications / for / both / theory / and / practice',NULL,'''Study, which is the most extensive yet undertaken, reaches conclusions that have significant implications.''','medium'),
  (cid,80,266,'gap_fill','[TOEFL Writing] The _____ (result), _____ (which) _____ (emerge) _____ (from) _____ (a) _____ (rigorous) _____ (analytical) _____ (process), _____ (support) _____ (the) _____ (core) _____ (hypothesis) _____ (while) _____ (also) _____ (reveal) _____ (several) _____ (unexpected) _____ (finding) _____ (that) _____ (warrant) _____ (further) _____ (investigation).','results / which / emerge / from / a / rigorous / analytical / process / support / the / core / hypothesis / while / also / revealing / several / unexpected / findings / that / warrant / further / investigation',NULL,'''Results, which emerge from a rigorous process, support hypothesis while also revealing findings that warrant investigation.''','medium'),
  (cid,80,267,'gap_fill','[TOEFL Writing] The _____ (authors), _____ (who) _____ (acknowledge) _____ (the) _____ (limitation) _____ (of) _____ (their) _____ (approach) _____ (with) _____ (commendable) _____ (candor), _____ (nevertheless) _____ (make) _____ (a) _____ (persuasive) _____ (case) _____ (for) _____ (their) _____ (central) _____ (claim).','authors / who / acknowledge / the / limitations / of / their / approach / with / commendable / candor / nevertheless / make / a / persuasive / case / for / their / central / claim',NULL,'''Authors, who acknowledge limitations with commendable candor, nevertheless make a persuasive case.''','medium'),
  (cid,80,268,'gap_fill','[TOEFL Writing] The _____ (conclusion), _____ (which) _____ (the) _____ (evidence) _____ (strongly) _____ (support), _____ (have) _____ (important) _____ (practical) _____ (implication) _____ (for) _____ (those) _____ (responsible) _____ (for) _____ (design) _____ (the) _____ (next) _____ (generation) _____ (of) _____ (reform).','conclusion / which / the / evidence / strongly / supports / has / important / practical / implications / for / those / responsible / for / designing / the / next / generation / of / reforms',NULL,'''Conclusion, which the evidence strongly supports, has important practical implications for those responsible for designing reforms.''','medium'),
  (cid,80,269,'multiple_choice','Which sentence MOST elegantly uses a non-defining clause as a concluding device?','The analysis reaches a conclusion that the evidence strongly supports: that institutional quality, which determines more than any other factor whether a state can translate economic potential into human welfare, must be treated as a central priority of development policy.','["The analysis reaches a conclusion supported by evidence: institutional quality determines more than any other factor whether a state can translate economic potential into human welfare.","The analysis reaches a conclusion that the evidence strongly supports: that institutional quality, which determines more than any other factor whether a state can translate economic potential into human welfare, must be treated as a central priority of development policy.","The analysis reaches a conclusion: institutional quality which determines more than any other factor must be treated as a central priority of development policy.","The analysis reaches the conclusion that institutional quality, that determines development outcomes, must be treated as a central priority of policy."]','Option B: non-defining clause ''which determines more than any other factor'' embedded within the appositive conclusion clause.','hard'),
  (cid,80,270,'production','[TOEFL Writing — 200 words] Write a conclusion on what governance reform requires, using non-defining clauses throughout.','',NULL,'Governance reform, which is among the most difficult and consequential undertakings that any society can attempt, requires a combination of political will, analytical rigor, and organizational competence that is rarely available in sufficient quantity simultaneously. The reforms that have succeeded — whose designers often had the advantage of a clear political mandate, adequate resources, and a sufficiently stable environment to allow implementation to proceed — demonstrate that the aspiration is realistic even if the achievement is rare. The institutions that have been transformed most effectively are those whose leaders understood that formal design, though necessary, is insufficient on its own: that the culture, the incentives, and the informal norms that shape daily behavior matter at least as much as the rules and structures that appear on paper. The lesson, which is both humbling and clarifying, is that good governance is not a destination that can be reached and then maintained without ongoing investment — it is a practice that requires continuous attention, adaptation, and the willingness to confront the gap between aspiration and reality honestly. Societies that accept this lesson, and whose leaders are willing to invest in the unglamorous work of institutional maintenance and improvement, are those that most consistently deliver the quality of governance that their populations deserve.','hard'),
  (cid,80,271,'gap_fill','[TOEFL Writing] The _____ (reform) _____ (agenda), _____ (which) _____ (develop/passive) _____ (through) _____ (extensive) _____ (consultation), _____ (now) _____ (require) _____ (the) _____ (political) _____ (commitment) _____ (and) _____ (resource) _____ (that) _____ (alone) _____ (can) _____ (translate) _____ (aspiration) _____ (into) _____ (reality).','reform / agenda / which / was developed / through / extensive / consultation / now / requires / the / political / commitment / and / resources / that / alone / can / translate / aspiration / into / reality',NULL,'''Reform agenda, which was developed through extensive consultation, now requires commitment and resources that alone can translate aspiration.''','medium'),
  (cid,80,272,'gap_fill','[TOEFL Writing] The _____ (evidence), _____ (which) _____ (span) _____ (multiple) _____ (decade) _____ (and) _____ (context), _____ (point) _____ (consistently) _____ (in) _____ (the) _____ (same) _____ (direction) — _____ (a) _____ (finding) _____ (that) _____ (should) _____ (increase) _____ (rather) _____ (than) _____ (diminish) _____ (our) _____ (confidence) _____ (in) _____ (the) _____ (core) _____ (claim).','evidence / which / spans / multiple / decades / and / contexts / points / consistently / in / the / same / direction / a / finding / that / should / increase / rather / than / diminish / our / confidence / in / the / core / claim',NULL,'''Evidence, which spans multiple decades, points consistently — a finding that should increase confidence in the core claim.''','medium'),
  (cid,80,273,'gap_fill','[TOEFL Writing] In _____ (conclusion), _____ (the) _____ (analysis) _____ (presented) _____ (here), _____ (which) _____ (draw) _____ (on) _____ (a) _____ (wide) _____ (range) _____ (of) _____ (evidence), _____ (support) _____ (the) _____ (view) _____ (that) _____ (institutional) _____ (quality) _____ (is) _____ (both) _____ (determinable) _____ (and) _____ (improvable) — _____ (a) _____ (conclusion) _____ (with) _____ (profound) _____ (implications) _____ (for) _____ (policy).','In / conclusion / the / analysis / presented / here / which / draws / on / a / wide / range / of / evidence / supports / the / view / that / institutional / quality / is / both / determinable / and / improvable / a / conclusion / with / profound / implications / for / policy',NULL,'''Analysis presented here, which draws on wide evidence, supports the view — a conclusion with profound implications.''','medium'),
  (cid,80,274,'production','[TOEFL Writing — 200 words] Final capstone 200 words: What the most effective institutions have in common, using non-defining clauses throughout.','',NULL,'The most effective institutions, whose performance has been sustained across generations and across dramatically shifting environmental conditions, share a set of characteristics that can be identified with some confidence. They possess a clarity of mission, which is reinforced rather than eroded by the organizational cultures that have developed around them, and which is understood and taken seriously at every level of the hierarchy. They have governance structures, designed after considerable deliberation about the risks of capture and misuse of authority, that provide sufficient checks on the exercise of discretion without preventing the timely and effective exercise of the functions the institution exists to perform. They have invested in the quality of their people, who are selected, trained, and rewarded in ways that reinforce commitment to the institutional mission rather than to personal advancement. And they have developed the capacity to learn — feedback systems, review processes, and leadership cultures that welcome rather than suppress information about what is not working. The institutions that achieve all of these things simultaneously are rare, which is why their performance stands out so clearly in comparative analysis. But their rarity is not an argument against the aspiration — it is an argument for the investment and sustained commitment that building institutions of this quality requires. The work is hard; the results, which accumulate slowly and compound over time, are worth it.','hard'),
  (cid,80,275,'gap_fill','[TOEFL Writing] This _____ (paper), _____ (which) _____ (begin) _____ (with) _____ (a) _____ (question) _____ (about) _____ (what) _____ (make) _____ (institution) _____ (effective), _____ (end) _____ (with) _____ (a) _____ (conclusion) _____ (about) _____ (what) _____ (make) _____ (reform) _____ (possible) — _____ (a) _____ (trajectory) _____ (that) _____ (reflect) _____ (the) _____ (logic) _____ (of) _____ (the) _____ (inquiry) _____ (itself).','paper / which / began / with / a / question / about / what / makes / institutions / effective / ends / with / a / conclusion / about / what / makes / reform / possible / a / trajectory / that / reflects / the / logic / of / the / inquiry / itself',NULL,'''Paper, which began with a question, ends with a conclusion — a trajectory that reflects the logic of the inquiry itself.''','medium'),
  (cid,80,276,'gap_fill','[TOEFL Writing] The _____ (scholars) _____ (whose) _____ (work) _____ (has) _____ (most) _____ (influenced) _____ (this) _____ (analysis), _____ (many) _____ (of) _____ (whom) _____ (reach) _____ (conclusions) _____ (that) _____ (this) _____ (paper) _____ (build) _____ (on) _____ (while) _____ (also) _____ (departing) _____ (from) _____ (them), _____ (deserve) _____ (acknowledgment) _____ (for) _____ (the) _____ (foundations) _____ (they) _____ (have) _____ (laid).','scholars / whose / work / has / most / influenced / this / analysis / many / of / whom / reached / conclusions / that / this / paper / builds / on / while / also / departing / from / them / deserve / acknowledgment / for / the / foundations / they / have / laid',NULL,'''Scholars, whose work has most influenced this analysis, many of whom reached conclusions, deserve acknowledgment.''','hard'),
  (cid,80,277,'gap_fill','[TOEFL Writing] The _____ (question) _____ (with) _____ (which) _____ (this) _____ (paper) _____ (begin) — _____ (what) _____ (determine) _____ (whether) _____ (institution) _____ (perform) _____ (effectively) — _____ (not) _____ (fully) _____ (answer/passive) _____ (here), _____ (which) _____ (is) _____ (as) _____ (it) _____ (should) _____ (be): the _____ (question) _____ (is) _____ (too) _____ (important) _____ (to) _____ (close) _____ (prematurely).','question / with / which / this / paper / begins / what / determines / whether / institutions / perform / effectively / is / not / fully / answered / here / which / is / as / it / should / be / question / is / too / important / to / close / prematurely',NULL,'''Question with which this paper begins is not fully answered, which is as it should be — too important to close prematurely.''','hard'),
  (cid,80,278,'production','[TOEFL Writing — 200 words] Write a final paragraph on governance as a continuous practice, using non-defining clauses throughout.','',NULL,'Governance, which is often discussed as if it were a technical problem with a determinate solution, is better understood as a continuous practice that requires ongoing attention, adaptation, and renewal. The institutions through which governance is exercised — however well-designed at their creation — are subject to pressures that, over time, tend to erode the qualities that made them effective: the clarity of mission, the commitment to accountability, the culture of learning, and the integrity of the people who lead them. The societies that maintain the quality of their governance over extended periods, whose experience provides the most instructive examples in comparative analysis, are those that have developed cultures and institutions that support the ongoing work of institutional maintenance — not as a special project but as a normal feature of how they manage their collective affairs. The challenge, which is as much political as technical, is to sustain the investment in institutional quality during periods when the consequences of under-investment are not yet visible — before the erosion has advanced to the point where the costs of neglect become undeniable. That is the hardest part of governance, not the design of better institutions but the maintenance of those that exist — and it is, in the end, the most important.','hard'),
  (cid,80,279,'gap_fill','[TOEFL Writing] Governance, _____ (which) _____ (require) _____ (ongoing) _____ (investment) _____ (to) _____ (sustain), _____ (cannot) _____ (treat/passive) _____ (as) _____ (a) _____ (problem) _____ (that) _____ (solve/passive) _____ (once) _____ (and) _____ (for) _____ (all) — _____ (it) _____ (is) _____ (a) _____ (practice), _____ (not) _____ (a) _____ (achievement).','which / requires / ongoing / investment / to / sustain / cannot / be treated / as / a / problem / that / is solved / once / and / for / all / it / is / a / practice / not / an / achievement',NULL,'''Governance, which requires ongoing investment, cannot be treated as a problem that is solved once — it is a practice, not an achievement.''','medium'),
  (cid,80,280,'gap_fill','[TOEFL Writing] The _____ (work) _____ (of) _____ (building) _____ (and) _____ (sustaining) _____ (good) _____ (governance), _____ (which) _____ (demand) _____ (patience) _____ (and) _____ (persistence) _____ (across) _____ (generation), _____ (is) _____ (the) _____ (most) _____ (important) _____ (work) _____ (that) _____ (any) _____ (society) _____ (undertake) — _____ (and) _____ (the) _____ (one) _____ (least) _____ (often) _____ (adequately) _____ (reward).','work / of / building / and / sustaining / good / governance / which / demands / patience / persistence / across / generations / is / the / most / important / work / that / any / society / undertakes / and / the / one / least / often / adequately / rewarded',NULL,'''Work of building governance, which demands patience across generations, is the most important work — and the one least often rewarded.''','medium'),
  (cid,80,281,'production','[TOEFL Writing — Final capstone 200 words] Write a conclusion on institutional leadership, using non-defining clauses throughout.','',NULL,'Institutional leadership, which has been examined throughout this paper as both a product of institutional design and an independent determinant of institutional performance, emerges from the analysis as a factor whose importance it would be difficult to overstate. The leaders who have made the greatest difference to the institutions they have served — whose tenures are studied precisely because they changed the trajectory of organizations that would otherwise have continued on declining or stagnant paths — share characteristics that are partially learnable but not fully teachable. They possess a clarity about the mission of the institution they lead, which allows them to make decisions in complex situations without losing sight of what the institution is for. They have the capacity to build and sustain coalitions of support, both within the institution and beyond it, whose breadth and depth determine what is politically feasible. And they demonstrate, through consistent behavior over time, that the values they articulate are genuine rather than rhetorical — a quality, it should be noted, that organizational members are exceptionally skilled at detecting. The institutions that attract and retain leaders of this quality are those that have themselves developed the cultures and structures that make the exercise of this kind of leadership both possible and valued. Investing in those cultures and structures is, in the end, what investing in institutional quality means.','hard'),
  (cid,80,282,'gap_fill','[TOEFL Writing] The _____ (analysis) _____ (complete), _____ (the) _____ (argument) _____ (make), _____ (the) _____ (evidence) _____ (review/passive) — _____ (what) _____ (remain) _____ (is) _____ (the) _____ (work) _____ (of) _____ (application), _____ (which) _____ (is) _____ (the) _____ (hardest) _____ (part) _____ (and) _____ (the) _____ (most) _____ (consequential).','analysis / complete / the / argument / made / the / evidence / reviewed / what / remains / is / the / work / of / application / which / is / the / hardest / part / and / the / most / consequential',NULL,'Absolute constructions ''analysis complete, argument made, evidence reviewed'' + ''what remains is the work of application, which is the hardest part.''','hard'),
  (cid,80,283,'gap_fill','[TOEFL Writing] The _____ (institutions) _____ (through) _____ (which) _____ (we) _____ (govern) _____ (ourselves), _____ (whose) _____ (quality) _____ (determines) _____ (so) _____ (much) _____ (of) _____ (what) _____ (is) _____ (possible) _____ (in) _____ (collective) _____ (life), _____ (deserve) _____ (the) _____ (investment) _____ (of) _____ (attention) _____ (and) _____ (resource) _____ (that) _____ (their) _____ (importance) _____ (warrants).','institutions / through / which / we / govern / ourselves / whose / quality / determines / so / much / of / what / is / possible / in / collective / life / deserve / the / investment / of / attention / and / resources / that / their / importance / warrants',NULL,'''Institutions, through which we govern ourselves, whose quality determines so much, deserve the investment that their importance warrants.''','hard'),
  (cid,80,284,'production','[TOEFL Writing — Final 200 words] Write a conclusion using non-defining clauses, participle phrases, and appositives on what makes governance reform succeed.','',NULL,'Governance reform, a process that combines the intellectual demands of careful diagnosis with the political demands of building and sustaining coalitions for change, succeeds when several conditions are present simultaneously. The reform must be grounded in an accurate diagnosis of what is actually wrong — not the proximate symptoms, which are often visible, but the underlying causes, which are often structural and therefore less amenable to simple intervention. The coalition that supports the reform, which must be broad enough to survive the inevitable opposition from those whose interests are threatened by change, must be built before the reform is announced rather than assembled afterward — a sequencing that requires patience and political skill but significantly improves the probability of success. The implementation plan, developed in genuine partnership with those responsible for execution rather than handed down to them, must be realistic about the time and resources required — an underestimation of these that is the single most common source of reform failure. And the feedback mechanisms, established at the outset so that early evidence of what is working and what is not can reach those with the authority to authorize adjustments, must be genuinely used rather than treated as a compliance exercise. When all of these conditions are met — which is rare, which is why successful reform is rare — the results can be transformative.','hard'),
  (cid,80,285,'gap_fill','[TOEFL Writing] The _____ (work) _____ (done), _____ (the) _____ (argument) _____ (made), _____ (the) _____ (evidence) _____ (examine/passive), _____ (it) _____ (remain) _____ (only) _____ (to) _____ (act) — _____ (a) _____ (step) _____ (that) _____ (no) _____ (analysis), _____ (however) _____ (rigorous), _____ (can) _____ (substitute) _____ (for).','work / done / the / argument / made / the / evidence / examined / it / remains / only / to / act / a / step / that / no / analysis / however / rigorous / can / substitute / for',NULL,'Absolute constructions ''work done, argument made, evidence examined'' + ''a step that no analysis can substitute for.''','hard'),
  (cid,80,286,'gap_fill','[TOEFL Writing] The _____ (task) _____ (ahead) _____ (is) _____ (difficult), _____ (which) _____ (is) _____ (not) _____ (a) _____ (reason) _____ (to) _____ (avoid) _____ (it) _____ (but) _____ (a) _____ (reason) _____ (to) _____ (approach) _____ (it) _____ (with) _____ (the) _____ (seriousness) _____ (that) _____ (its) _____ (importance) _____ (demand).','task / ahead / is / difficult / which / is / not / a / reason / to / avoid / it / but / a / reason / to / approach / it / with / the / seriousness / that / its / importance / demands',NULL,'''Task ahead is difficult, which is not a reason to avoid it but to approach it with seriousness that its importance demands.''','medium'),
  (cid,80,287,'gap_fill','[TOEFL Writing] The _____ (institutions) _____ (we) _____ (build), _____ (whose) _____ (quality) _____ (will) _____ (shape) _____ (the) _____ (experience) _____ (of) _____ (generations) _____ (yet) _____ (unborn), _____ (represent) _____ (our) _____ (most) _____ (lasting) _____ (contribution) _____ (to) _____ (the) _____ (collective) _____ (future).','institutions / we / build / whose / quality / will / shape / the / experience / of / generations / yet / unborn / represent / our / most / lasting / contribution / to / the / collective / future',NULL,'''Institutions we build, whose quality will shape the experience of generations yet unborn, represent our most lasting contribution.''','medium'),
  (cid,80,288,'production','[TOEFL Writing — 200 words] Final concluding paragraph on what future governance scholarship should focus on.','',NULL,'The agenda for future governance scholarship, which must balance the demand for theoretical rigor with the urgency of practical problems, should be organized around several priorities. The most pressing is the development of a more robust understanding of the conditions under which institutional reform succeeds — not just the cases, which have been documented extensively, but the mechanisms, whose identification would allow the findings to be applied in new contexts rather than simply replicated in familiar ones. A second priority is the development of better measures of institutional quality, which would allow researchers to track change over time and across contexts with greater precision than current indicators permit. The indicators currently available, which rely heavily on expert perceptions and therefore capture reputation as much as reality, provide at best a rough approximation of the multidimensional concept they are supposed to measure. A third priority is the integration of insights from multiple disciplines — economics, political science, sociology, organizational behavior, and public administration — whose separate literatures have each illuminated different aspects of a problem that is inherently multidisciplinary. The governance of governance research, a meta-level problem that has received insufficient attention, is itself worth studying: the incentive structures, which shape what questions get asked and what methods get used, determine the quality and relevance of the knowledge produced. Getting that right is the foundation on which everything else depends.','hard'),
  (cid,80,289,'gap_fill','[TOEFL Writing] The _____ (generations) _____ (that) _____ (follow) _____ (us), _____ (whose) _____ (welfare) _____ (depends) _____ (in) _____ (part) _____ (on) _____ (the) _____ (quality) _____ (of) _____ (the) _____ (institutions) _____ (we) _____ (leave) _____ (them), _____ (deserve) _____ (our) _____ (best) _____ (effort) _____ (at) _____ (building) _____ (those) _____ (institutions) _____ (well).','generations / that / follow / us / whose / welfare / depends / in / part / on / the / quality / of / the / institutions / we / leave / them / deserve / our / best / effort / at / building / those / institutions / well',NULL,'''Generations that follow us, whose welfare depends on quality of institutions we leave them, deserve our best effort.''','medium'),
  (cid,80,290,'gap_fill','[TOEFL Writing] We _____ (end) _____ (as) _____ (we) _____ (began): _____ (with) _____ (a) _____ (question) _____ (whose) _____ (answer) _____ (matters) _____ (more) _____ (than) _____ (most) — _____ (how) _____ (do) _____ (we) _____ (build) _____ (institution) _____ (that) _____ (serve) _____ (the) _____ (public) _____ (interest) _____ (reliably) _____ (and) _____ (durably) — _____ (and) _____ (with) _____ (the) _____ (conviction) _____ (that) _____ (the) _____ (effort) _____ (to) _____ (answer) _____ (it) _____ (is) _____ (worthwhile).','end / as / we / began / with / a / question / whose / answer / matters / more / than / most / how / do / we / build / institutions / that / serve / the / public / interest / reliably / and / durably / and / with / the / conviction / that / the / effort / to / answer / it / is / worthwhile',NULL,'''A question whose answer matters more than most'' + ''institutions that serve the public interest durably.''','medium'),
  (cid,80,291,'production','[TOEFL Writing — Final 200 words] Final capstone: Why governance matters, using non-defining clauses as the primary device.','',NULL,'Governance matters because people matter — and the institutions through which governance is exercised, whose quality determines whether people have access to security, justice, health, education, and opportunity, are too important to be treated as a technical afterthought. The populations that benefit most from effective governance are often those who are least able to advocate for themselves, whose voices are most easily ignored in the political processes that determine how public resources are allocated and how public authority is exercised. The institutions whose performance most affects these populations — public health systems, judicial bodies, educational institutions, social protection programs — are precisely those that are most subject to under-investment and neglect in political systems that respond primarily to the preferences of the organized and the powerful. The analysis presented in this paper, which has attempted to illuminate what makes these institutions work and what makes them fail, is ultimately in the service of this practical purpose: to improve the quality of the governance that these populations receive. That purpose, which is both intellectually and morally demanding, is what gives the study of governance its distinctive urgency. The analytical tools, the conceptual frameworks, the empirical evidence — all of these are in the service of the fundamental question of how to build institutions that treat all people with the dignity and effectiveness they deserve. That question, which will not be answered finally or fully here, is worth asking again and again until the answer improves.','hard'),
  (cid,80,292,'gap_fill','[TOEFL Writing] The _____ (study) _____ (of) _____ (governance), _____ (which) _____ (has) _____ (occupied) _____ (generations) _____ (of) _____ (scholars), _____ (has) _____ (not) _____ (exhaust/passive) _____ (its) _____ (questions) — _____ (it) _____ (has) _____ (clarify/passive) _____ (them), _____ (which) _____ (is) _____ (the) _____ (most) _____ (that) _____ (any) _____ (field) _____ (of) _____ (inquiry) _____ (can) _____ (hope) _____ (for).','study / of / governance / which / has / occupied / generations / of / scholars / has / not / been exhausted / its / questions / has / been clarified / them / which / is / the / most / that / any / field / of / inquiry / can / hope / for',NULL,'''Study of governance, which has occupied generations, has not exhausted its questions — has clarified them, which is the most any field can hope for.''','hard'),
  (cid,80,293,'gap_fill','[TOEFL Writing] The _____ (field), _____ (whose) _____ (tools) _____ (have) _____ (sharpen/passive) _____ (considerably) _____ (in) _____ (recent) _____ (decade), _____ (is) _____ (better) _____ (equip/passive) _____ (than) _____ (ever) _____ (to) _____ (contribute) _____ (to) _____ (the) _____ (practical) _____ (challenge) _____ (of) _____ (governance) _____ (improvement) — _____ (a) _____ (contribution) _____ (that) _____ (is) _____ (long) _____ (overdue).','field / whose / tools / have / been sharpened / considerably / in / recent / decades / is / better / equipped / than / ever / to / contribute / to / the / practical / challenge / of / governance / improvement / a / contribution / that / is / long / overdue',NULL,'''Field, whose tools have been sharpened, is better equipped to contribute — a contribution that is long overdue.''','medium'),
  (cid,80,294,'gap_fill','[TOEFL Writing] This _____ (is) _____ (the) _____ (end) _____ (of) _____ (the) _____ (analysis) _____ (but) _____ (not) _____ (the) _____ (end) _____ (of) _____ (the) _____ (question) — _____ (which), _____ (as) _____ (all) _____ (important) _____ (question) _____ (do), _____ (will) _____ (survive) _____ (the) _____ (answer) _____ (given) _____ (here) _____ (and) _____ (generate) _____ (new) _____ (inquiry).','is / the / end / of / the / analysis / not / the / end / of / the / question / which / as / all / important / questions / do / will / survive / the / answer / given / here / and / generate / new / inquiry',NULL,'''End of the analysis but not of the question — which, as all important questions do, will survive the answer given here.''','medium'),
  (cid,80,295,'production','[TOEFL Writing — 200 words] Final synthesis paragraph on governance reform, institutions, and accountability, using non-defining clauses throughout.','',NULL,'The argument of this paper, which has moved from a diagnosis of what makes institutions fail to an account of what makes reform succeed, rests on a foundation of evidence drawn from multiple disciplines and multiple contexts. The institutions that have performed best, whose experience provides the strongest basis for practical lessons, have done so not by following a template but by developing a deep and practical understanding of what they are trying to achieve, who they are accountable to, and what they must do to maintain the trust of those on whom their legitimacy depends. The reforms that have succeeded, which are fewer than reformers invariably hope for when they begin, have shared the characteristic of genuine engagement with implementation — of treating the process of getting from design to delivery not as an administrative detail but as the central challenge. The scholars and practitioners who have contributed most to improving governance, many of whom have worked at the intersection of research and practice rather than staying safely within either domain, have demonstrated that the gap between knowledge and action can be narrowed, even if it cannot be closed. This paper, which has attempted to contribute to that effort, ends with the hope that its findings will be found useful by those engaged in the difficult and consequential work of making governance better.','hard'),
  (cid,80,296,'gap_fill','[TOEFL Writing] Institutions, _____ (whose) _____ (performance) _____ (shapes) _____ (every) _____ (dimension) _____ (of) _____ (collective) _____ (life), _____ (deserve) _____ (the) _____ (sustained) _____ (attention) _____ (of) _____ (scholars), _____ (practitioners), _____ (and) _____ (citizens) _____ (alike) — _____ (each) _____ (of) _____ (whom) _____ (has) _____ (a) _____ (stake) _____ (in) _____ (getting) _____ (them) _____ (right).','whose / performance / shapes / every / dimension / of / collective / life / deserve / the / sustained / attention / of / scholars / practitioners / and / citizens / alike / each / of / whom / has / a / stake / in / getting / them / right',NULL,'''Institutions, whose performance shapes every dimension, deserve sustained attention — each of whom has a stake in getting them right.''','medium'),
  (cid,80,297,'gap_fill','[TOEFL Writing] The _____ (road) _____ (is) _____ (long), _____ (the) _____ (challenges) _____ (are) _____ (real), _____ (and) _____ (the) _____ (outcome) _____ (is) _____ (uncertain) — _____ (which) _____ (is) _____ (to) _____ (say) _____ (that) _____ (the) _____ (work) _____ (of) _____ (governance) _____ (reform) _____ (is) _____ (no) _____ (different) _____ (from) _____ (any) _____ (other) _____ (serious) _____ (human) _____ (enterprise).','road / is / long / the / challenges / are / real / the / outcome / is / uncertain / which / is / to / say / that / the / work / of / governance / reform / is / no / different / from / any / other / serious / human / enterprise',NULL,'''Road is long, challenges real, outcome uncertain — which is to say that governance reform is no different from any other serious human enterprise.''','easy'),
  (cid,80,298,'gap_fill','[TOEFL Writing] The _____ (future), _____ (which) _____ (is) _____ (not) _____ (determine), _____ (depends) _____ (on) _____ (choices) _____ (not) _____ (yet) _____ (made) — _____ (a) _____ (fact) _____ (that) _____ (is) _____ (both) _____ (humbling) _____ (and) _____ (empowering), _____ (and) _____ (that) _____ (makes) _____ (the) _____ (work) _____ (of) _____ (analysis) _____ (genuinely) _____ (consequential).','future / which / is / not / determined / depends / on / choices / not / yet / made / a / fact / that / is / both / humbling / and / empowering / that / makes / the / work / of / analysis / genuinely / consequential',NULL,'''Future, which is not determined, depends on choices not yet made — a fact that is both humbling and empowering."','easy'),
  (cid,80,299,'production','[TOEFL Writing — 200 words] Final concluding paragraph on what the analysis has demonstrated, using non-defining clauses throughout.','',NULL,'The analysis presented in this paper has, it is hoped, demonstrated several things that are worth knowing about governance and its reform. The institutions through which collective decisions are made, whose quality is the single most important determinant of the welfare of the populations they serve, can be understood analytically with a precision that earlier generations of scholars could not achieve — and that understanding, which is incomplete and contested in important ways, is nonetheless sufficient to support practical action. The reforms that have succeeded, whose common features can be identified with growing confidence, provide a basis for learning that should inform future reform efforts even if it cannot guarantee their success. The scholars whose work has contributed most to this understanding, many of whom have worked across the boundaries that academic disciplines erect, have demonstrated that the governance of institutions is a subject of genuine intellectual depth and practical importance — one that rewards sustained and rigorous investigation. The paper ends, therefore, not with a claim to have solved the problem but with the conviction that the problem is worth solving, that progress toward its solution is possible, and that the combination of analytical rigor and practical engagement that characterizes the best work in this field is the approach most likely to generate the knowledge that practice requires.','hard'),
  (cid,80,300,'production','[TOEFL Writing — Final 200 words] Final capstone 300: Governance, institutions, and the future.','',NULL,'Governance, which determines more than any other single factor whether collective human action achieves the purposes it is directed toward, is ultimately a moral as well as a technical enterprise. The institutions whose performance shapes the daily lives of billions of people — the courts that adjudicate disputes, the agencies that deliver services, the bodies that make and enforce rules — are not merely mechanisms for the efficient production of public goods. They are expressions of a society''s commitments about what matters, who counts, and what forms of treatment people are owed. The failures of governance, which are documented extensively in the literature this paper has drawn on, are not merely inefficiencies — they are injustices, whose costs fall disproportionately on those who are least able to compensate for them through private means. The improvements that are possible, which the analysis has attempted to describe with as much precision as the evidence allows, are not merely welfare gains — they are expansions of justice, whose beneficiaries are those who currently bear the heaviest costs of poor governance. The work of governance reform, understood in this light, is among the most important things that scholars, practitioners, and citizens can contribute to. It is difficult work, which is not a reason to avoid it. It is necessary work, which is reason enough to begin.','hard')

